import (
	context "context"
	fern "github.com/openapi-wildcard-errors/fern"
	fernclient "github.com/openapi-wildcard-errors/fern/client"
)

client := fernclient.NewClient()
response, err := client.Items.CreateItem(
	context.TODO(),
	&fern.CreateItemRequest{
		Name: "name",
	},
)

